const messages = $input.all();

const conversation_history = messages.map(item => ({
  role: item.json.role,
  content: item.json.content,
  timestamp: item.json.created_at
}));

const current_message =
  [...conversation_history]
    .reverse()
    .find(message => message.role === 'customer')?.content || '';

return [
  {
    json: {
      current_message,
      conversation_history
    }
  }
];

const startedAt = Number(
  $('Start Triage Time').first().json.triage_started_at
);

if (!Number.isFinite(startedAt) || startedAt <= 0) {
  throw new Error("Triage start timestamp is missing");
}

const latencyMs = Date.now() - startedAt;

return {
  json: {
    ...$json,
    triage_latency_ms: latencyMs
  }
};

const rows = $input.all().map(item => item.json);
const data = rows[0] ?? {};

const prepared = $('Prepare Evaluation Data').first().json;

return [{
  json: {
    conversation_id: data.conversation_id ?? prepared.conversation_id,
    message_id: data.customer_message_id ?? null,

    customer_message: data.customer_message ?? null,
    response: data.assistant_message ?? prepared.response ?? '',

    // Conversation memory for evaluation
    conversation_history: data.conversation_history ?? [],

    expected_intent: null,
    actual_intent: null,
    expected_department: null,
    actual_department: prepared.actual_department ?? null,
    expected_agent: null,
    actual_agent: data.actual_agent ?? null,

    routing_result: null,
    response_result: null,
    groundedness_score: null,
    relevance_score: null,
    accuracy_score: null,
    resolved_by_ai: null,

    escalation_required: prepared.needs_human ?? false,
    evaluator_model: null,

    evaluation_details: {
      confidence: prepared.confidence ?? null,
      language: prepared.language ?? 'und',
      source: 'autorex_evaluation'
    }
  }
}];

