const data = $json;

// Extract the actual triage result.
const triage =
  data.output ??
  data.result ??
  data;

// Validate that a triage classification is available.
const requiredFields = [
  "intent",
  "category",
  "priority",
  "sentiment",
  "language",
  "confidence",
  "needs_human",
  "reason"
];

const missingFields = requiredFields.filter(
  field => triage[field] === undefined || triage[field] === null
);

if (missingFields.length > 0) {
  throw new Error(
    `Triage result is missing required fields: ${missingFields.join(", ")}`
  );
}

// Preserve the original customer message and conversation context.
const currentMessage =
  data.current_message ??
  triage.customer_message ??
  "";

const customerMessage =
  triage.customer_message ??
  currentMessage;

const conversationHistory =
  Array.isArray(data.conversation_history)
    ? data.conversation_history
    : [];

// Fixed category-to-department mapping.
const categoryToDepartment = {
  billing: "billing",
  account: "account",
  technical: "technical_support",
  sales: "sales",
  general: "general_support"
};

const category = String(triage.category)
  .toLowerCase()
  .trim();

if (!categoryToDepartment[category]) {
  throw new Error(`Invalid triage category: ${category}`);
}

// Validate the department instead of silently accepting mismatches.
const expectedDepartment = categoryToDepartment[category];

if (
  triage.department &&
  triage.department !== expectedDepartment
) {
  throw new Error(
    `Department mismatch: expected ${expectedDepartment}, received ${triage.department}`
  );
}

const confidence = Number(triage.confidence);

if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) {
  throw new Error(`Invalid triage confidence: ${triage.confidence}`);
}

return [
  {
    json: {
      ...data,
      current_message: currentMessage,
      customer_message: customerMessage,
      conversation_history: conversationHistory,

      intent: String(triage.intent),
      category,
      department: expectedDepartment,
      priority: String(triage.priority),
      sentiment: String(triage.sentiment),
      language: String(triage.language),
      confidence,
      needs_human: triage.needs_human === true,
      reason: String(triage.reason)
    }
  }
];

const data = $json.output ?? $json;
const conversationId =
  $('Resolve Conservation').first().json.conversation_id ?? null;

// The escalations.reason column is a Postgres enum; map the agent's
// free-text reason onto a valid label and keep the text as description.
const VALID_REASONS = [
  "customer_requested_human",
  "low_confidence",
  "high_risk",
  "policy_restriction",
  "repeated_failure",
  "negative_sentiment",
  "technical_limitation",
  "refund_request",
  "other"
];

function mapReason(text, d) {
  const t = (text || "").toLowerCase();
  if (VALID_REASONS.includes(t)) return t;
  if (Number(d.confidence) < 0.5) return "low_confidence";
  if (d.sentiment === "negative" || d.sentiment === "angry") return "negative_sentiment";
  if (/refund|charged twice|duplicate charge|double.?charg/.test(t)) return "refund_request";
  if (/human|agent|specialist|billing team|refer/.test(t)) return "customer_requested_human";
  if (/policy|not allowed|forbidden|compliance/.test(t)) return "policy_restriction";
  if (/cannot|can't|unable|limitation|not able/.test(t)) return "technical_limitation";
  if (/again|repeat|still|unresolved/.test(t)) return "repeated_failure";
  if (/risk|fraud|legal|urgent/.test(t)) return "high_risk";
  return "other";
}

const freeTextReason =
  data.reason || "Triage agent requested human escalation";

return [
  {
    json: {
      ...data,
      conversation_id: conversationId,
      escalation_status: "pending",
      escalation_reason: mapReason(freeTextReason, data),
      reason: freeTextReason
    }
  }
];

return {
  json: {
    chat_id: $('Normalize Message').first().json.chat_id,
    response: "Your request has been forwarded to a human support specialist. They will review it and get back to you.",
    escalation_status: "pending"
  }
};

