const data = $json.output ?? $json;
const conversationId =
  $('Resolve Conservation').first().json.conversation_id ?? null;

const reasonText = data.reason ?? "";
const confidence = Number(data.confidence ?? 0);

// Map the agent's free-text reason to a valid escalation_reason enum value
const allowedReasons = [
  "customer_requested_human",
  "low_confidence",
  "high_risk",
  "policy_restriction",
  "repeated_failure",
  "negative_sentiment",
  "technical_limitation",
  "refund_request",
  "other"
];
let escalationReason = "other";
if (allowedReasons.includes(reasonText)) {
  escalationReason = reasonText;
} else if (confidence < 0.5) {
  escalationReason = "low_confidence";
} else if (/human|agent|speak to|representative/i.test(reasonText)) {
  escalationReason = "customer_requested_human";
} else if (/refund|charge|billing|payment/i.test(reasonText)) {
  escalationReason = "refund_request";
} else if (/technical|not available|cannot|can't|unable/i.test(reasonText)) {
  escalationReason = "technical_limitation";
}

return {
  json: {
    department: data.department ?? null,
    response: data.response ?? "",
    needs_human:
      data.needs_human === true ||
      data.needs_human === "true",
    reason: reasonText,
    escalation_reason: escalationReason,
    confidence: confidence,
    conversation_id: conversationId
  }
};

return {
  json: {
    conversation_id: $json.conversation_id,
    chat_id: $json.chat_id,
    response: $json.response,
    department: $json.department,
    confidence: $json.confidence,
    language: $json.language || "en",
    needs_human: false
  }
};

const data = $json;

return {
  json: {
