    message_id: null,

    customer_message: null,
    response: data.response ?? "",

    actual_department: data.department ?? null,
    actual_agent: null,
    actual_intent: null,

    confidence: Number(data.confidence ?? 0),
    needs_human:
      data.needs_human === true ||
      data.needs_human === "true",

    language: data.language ?? "und",
    evaluation_status: "pending"
  }
};

