parameters.jsCode:
const data = $json;

let evaluation = data.output;

if (typeof evaluation === 'string') {
  try {
    evaluation = JSON.parse(evaluation);
  } catch (error) {
    throw new Error(
      `AI Evaluator returned invalid JSON: ${error.message}`
    );
  }
}

if (!evaluation || typeof evaluation !== 'object') {
  throw new Error('AI Evaluator returned an invalid evaluation object.');
}

const validResult = value =>
  ['pass', 'partial', 'fail', null].includes(value) ? value : null;

const validScore = value =>
  value === null ||
  (typeof value === 'number' && value >= 0 && value <= 1)
    ? value
    : null;

const validBoolean = value =>
  typeof value === 'boolean' ? value : null;

return {
  json: {
    ...data,
    response_result: validResult(evaluation.response_result),
    routing_result: validResult(evaluation.routing_result),
    groundedness_score: validScore(evaluation.groundedness_score),
    relevance_score: validScore(evaluation.relevance_score),
    accuracy_score: validScore(evaluation.accuracy_score),
    resolved_by_ai: validBoolean(evaluation.resolved_by_ai),
    feedback: evaluation.feedback ?? '',
    evaluation_details: {
      ...(data.evaluation_details ?? {}),
      ...(evaluation.evaluation_details ?? {})
    }
  }
};

const raw = $json.output;

let evaluation = raw;

if (typeof raw === 'string') {
  try {
    evaluation = JSON.parse(raw);
  } catch (error) {
    throw new Error(`Invalid evaluation JSON: ${error.message}`);
  }
}

if (!evaluation || typeof evaluation !== 'object') {
  evaluation = {
    response_result: $json.response_result ?? null,
    routing_result: $json.routing_result ?? null,
    groundedness_score: $json.groundedness_score ?? null,
    relevance_score: $json.relevance_score ?? null,
    accuracy_score: $json.accuracy_score ?? null,
    resolved_by_ai: $json.resolved_by_ai ?? null,
    feedback: $json.feedback ?? null,
    evaluation_details: $json.evaluation_details ?? {}
  };
}

return {
  json: {
    ...$json,
    output: evaluation,
    response_result: evaluation.response_result ?? null,
    routing_result: evaluation.routing_result ?? null,
    groundedness_score: evaluation.groundedness_score ?? null,
    relevance_score: evaluation.relevance_score ?? null,
    accuracy_score: evaluation.accuracy_score ?? null,
    resolved_by_ai: evaluation.resolved_by_ai ?? null,
    feedback: evaluation.feedback ?? null,
    evaluation_details: {
      ...($json.evaluation_details ?? {}),
      ...(evaluation.evaluation_details ?? {})
    }
  }
};

